//! Parity tests against numpy fixtures generated by `src/gen_dsp_fixtures.py`.
//!
//! Each test reads the SAME input bytes numpy used, runs the Rust transform and
//! compares to the expected output. Inputs/expected are little-endian f32.
#![allow(clippy::cast_possible_truncation)]

use std::fs;
use std::path::PathBuf;

use mpc_stemloop_dsp::{Dsp, HOP, magnitude, mask_ispec, spec};
use rustfft::num_complex::Complex;

fn fixture(name: &str) -> Vec<f32> {
    let mut p = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    p.push("tests/fixtures");
    p.push(format!("{name}.bin"));
    let bytes = fs::read(&p).unwrap_or_else(|e| panic!("read {}: {e}", p.display()));
    assert!(bytes.len() % 4 == 0, "{name}: not a multiple of 4 bytes");
    bytes
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

/// Max absolute and max relative error between two equal-length arrays.
fn errs(got: &[f32], want: &[f32]) -> (f64, f64) {
    assert_eq!(got.len(), want.len(), "length mismatch");
    let mut max_abs = 0.0_f64;
    let mut max_rel = 0.0_f64;
    for (&g, &w) in got.iter().zip(want.iter()) {
        let a = (f64::from(g) - f64::from(w)).abs();
        if a > max_abs {
            max_abs = a;
        }
        let denom = f64::from(w).abs() + 1e-6;
        let r = a / denom;
        if r > max_rel {
            max_rel = r;
        }
    }
    (max_abs, max_rel)
}

#[test]
fn stft_matches_numpy() {
    let dsp = Dsp::new();
    let x: Vec<f64> = fixture("stft_in_x").iter().map(|&v| f64::from(v)).collect();
    let (z, _f, t) = dsp.stft_row(&x, HOP);
    assert_eq!(t, 7);
    let got_r: Vec<f32> = z.iter().map(|c| c.re as f32).collect();
    let got_i: Vec<f32> = z.iter().map(|c| c.im as f32).collect();
    let (ar, rr) = errs(&got_r, &fixture("stft_out_zr"));
    let (ai, ri) = errs(&got_i, &fixture("stft_out_zi"));
    println!("stft re: max_abs={ar:.3e} max_rel={rr:.3e}");
    println!("stft im: max_abs={ai:.3e} max_rel={ri:.3e}");
    assert!(ar < 1e-4 && ai < 1e-4, "stft abs error too high");
}

#[test]
fn istft_matches_numpy() {
    let dsp = Dsp::new();
    let zr = fixture("istft_in_zr");
    let zi = fixture("istft_in_zi");
    let t = 7usize;
    let f = 2049usize;
    let z: Vec<Complex<f64>> = (0..f * t)
        .map(|k| Complex::new(f64::from(zr[k]), f64::from(zi[k])))
        .collect();
    let got: Vec<f32> = dsp
        .istft_row(&z, t, HOP, 7000)
        .iter()
        .map(|&v| v as f32)
        .collect();
    let (a, r) = errs(&got, &fixture("istft_out"));
    println!("istft: max_abs={a:.3e} max_rel={r:.3e}");
    assert!(a < 1e-4, "istft abs error too high");
}

#[test]
fn spec_and_magnitude_match_numpy() {
    let dsp = Dsp::new();
    let mix = fixture("spec_in_mix");
    let (zr, zi, le) = spec(&dsp, &mix, 1, 2, 7000);
    assert_eq!(le, 7);
    let (ar, rr) = errs(&zr, &fixture("spec_out_zr"));
    let (ai, ri) = errs(&zi, &fixture("spec_out_zi"));
    println!("spec re: max_abs={ar:.3e} max_rel={rr:.3e}");
    println!("spec im: max_abs={ai:.3e} max_rel={ri:.3e}");
    assert!(ar < 1e-4 && ai < 1e-4, "spec abs error too high");

    let mag = magnitude(&zr, &zi, 1, 2, le);
    let (am, _rm) = errs(&mag, &fixture("mag_out"));
    println!("magnitude: max_abs={am:.3e}");
    assert!(am < 1e-4, "magnitude abs error too high");
}

#[test]
fn mask_ispec_matches_numpy() {
    let dsp = Dsp::new();
    let xspec = fixture("maskispec_in_xspec");
    let got = mask_ispec(&dsp, &xspec, 1, 4, 4, 2048, 7, 7000);
    let (a, r) = errs(&got, &fixture("maskispec_out"));
    println!("mask_ispec: max_abs={a:.3e} max_rel={r:.3e}");
    assert!(a < 1e-4, "mask_ispec abs error too high");
}
